function retireMyTheatreFixture(PDO $db,array $fixture):void
{
    $owned=array_map('intval',array_values($fixture['users']));$students=[];if($owned){$q=$db->query("SELECT ur.user_id FROM auth_user_roles ur JOIN auth_roles r ON r.id=ur.role_id WHERE r.code='student' AND ur.user_id IN (".implode(',',$owned).")");$students=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}
    foreach($students as $id)$db->prepare("UPDATE users SET active=0,account_status='disabled' WHERE id=?")->execute([$id]);
    foreach($owned as $id){$db->prepare("UPDATE users SET active=0,account_status='disabled' WHERE id=?")->execute([$id]);$db->prepare('UPDATE auth_mobile_tokens SET revoked_at=COALESCE(revoked_at,NOW()) WHERE user_id=?')->execute([$id]);}
    foreach($fixture['productions'] as $id)$db->prepare("UPDATE productions SET lifecycle_stage='archived',status='archived',is_active=0 WHERE id=?")->execute([$id]);
}
